select `h`.`id` AS `id`,`h`.`campaign_id` AS `campaign_id`,`h`.`email` AS `email`,`h`.`time` AS `time`,`h`.`message` AS `message`,`h`.`details` AS `details`,`h`.`recipient_id` AS `recipient_id`,`h`.`source` AS `source`,coalesce(`a`.`revision`,0) AS `revision`,coalesce(`a`.`excluded`,0) AS `excluded`,coalesce(`a`.`time`,`h`.`time`) AS `effective_time`,coalesce(`a`.`message`,`h`.`message`) AS `effective_message`,coalesce(`a`.`details`,`h`.`details`) AS `effective_details` from (`event_history` `h` left join `ruphish_event_changes` `a` on(((`a`.`event_id` = `h`.`id`) and (`a`.`revision` = (select max(`latest`.`revision`) from `ruphish_event_changes` `latest` where (`latest`.`event_id` = `h`.`id`))))))
